package escuela.personal.service;

import escuela.personal.dto.*;
import escuela.admin.dto.OpcionAutocompletado;
import escuela.common.exception.ReglaNegocioException;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.data.domain.*;
import org.springframework.security.access.AccessDeniedException;
import java.time.*;
import java.math.BigDecimal;
import java.util.*;

@Service @RequiredArgsConstructor @Transactional(readOnly=true)
public class PreparacionNominaService {
 private final NamedParameterJdbcTemplate jdbc;
 private final EmpleadoService empleados;
 private final ProgramacionNominaService programacion;
 public record Contexto(ProgramacionNominaService.Periodo periodo,String calendario,String moneda,String fuentes,String sello,String advertencia){}
 public record Candidato(Long id,String codigo,String nombre,String grupo,String motivo,BigDecimal sueldo,BigDecimal percepciones,BigDecimal deducciones,BigDecimal aportaciones,BigDecimal propuesto,String moneda,String fuentes,String sello){public String token(){return id+":"+sello;}}
 public record Totales(int empleados,BigDecimal sueldo,BigDecimal percepciones,BigDecimal deducciones,BigDecimal aportaciones,BigDecimal propuesto){}
 public record Previa(Contexto contexto,List<Candidato> candidatos,Totales totales){}
 public record Borrador(Long id,Long periodoId,String nombre,String estado,int revision,Long version,String motivo,String periodoCodigo,String periodoNombre,String calendario,LocalDate inicio,LocalDate fin,LocalDate pago,String moneda,String selloPeriodo,int cantidad,BigDecimal propuesto){public String folio(){return "BOR-"+String.format(Locale.ROOT,"%06d",id);}}
 public record Guardado(Long id,Long empleadoId,String codigo,String nombre,BigDecimal sueldo,BigDecimal percepciones,BigDecimal deducciones,BigDecimal aportaciones,BigDecimal propuesto,String moneda,String sello,int revision){}
 public record Cobertura(String calendario,String codigo,String nombre,LocalDate inicio,LocalDate fin,LocalDate pago,String moneda){}
 public record Linea(String codigo,String nombre,String naturaleza,BigDecimal importe,String inicio,String fin){}
 public record Historia(String fecha,String usuario,String operacion,String motivo,int revision){}
 public record Revision(int numero,String fecha,String usuario,String motivo){}
 private MapSqlParameterSource p(boolean escritura){var a=empleados.autorizarSalarios(escritura);return new MapSqlParameterSource("institucion",a.institucionId()).addValue("actor",a.usuarioId());}
 private void activa(MapSqlParameterSource p){if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT activo FROM institucion WHERE id=:institucion FOR SHARE",p,Boolean.class)))throw regla("La institución está inactiva; sólo consulta.");}
 private void motivo(String m){if(m==null||m.isBlank()||m.length()>2000)throw regla("Explica el motivo obligatorio con máximo 2000 caracteres.");}
 private void version(Long actual,Long enviada){if(!Objects.equals(actual,enviada))throw regla("El borrador cambió en otra pestaña. Recarga antes de continuar; no se sobrescribieron cambios.");}
 public static String sello(String dato){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(dato.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 public Contexto contexto(Long id){
  var per=programacion.periodo(id);var cal=programacion.calendario(per.calendarioId());if(!per.estado().equals("PROGRAMADO"))throw regla("El periodo está cancelado; no puede prepararse ni actualizarse.");if(!cal.activo())throw regla("El calendario está inactivo; reactívalo antes de preparar o actualizar.");
  var par=p(false).addValue("id",id);String datos=jdbc.queryForObject("SELECT jsonb_build_object('periodo',to_jsonb(pe),'calendario',to_jsonb(c),'moneda',i.moneda_predeterminada)::text FROM periodo_nomina pe JOIN calendario_nomina c ON c.id=pe.calendario_id JOIN institucion i ON i.id=pe.institucion_id WHERE pe.id=:id AND pe.institucion_id=:institucion",par,String.class);
  String moneda=jdbc.queryForObject("SELECT moneda_predeterminada FROM institucion WHERE id=:institucion",par,String.class);
  String advertencia=!per.frecuencia().equals("MENSUAL")?"Sólo se prepara frecuencia mensual; semanal y quincenal requieren otra regla.":!per.inicio().equals(per.inicio().withDayOfMonth(1))||!per.fin().equals(per.inicio().withDayOfMonth(per.inicio().lengthOfMonth()))?"Periodo parcial: requiere revisión explícita; no se prorratean sueldos automáticamente.":"";
  return new Contexto(per,cal.codigo()+" · "+cal.nombre(),moneda,datos,sello(datos),advertencia);
 }
 private void bloquearPeriodo(Long id){var per=programacion.periodo(id);var par=p(true).addValue("id",id).addValue("cal",per.calendarioId());jdbc.queryForObject("SELECT id FROM calendario_nomina WHERE id=:cal AND institucion_id=:institucion FOR UPDATE",par,Long.class);jdbc.queryForObject("SELECT id FROM periodo_nomina WHERE id=:id AND institucion_id=:institucion FOR UPDATE",par,Long.class);}
 public List<OpcionAutocompletado> periodos(String q){var par=p(false);String texto=OrganizacionLaboralService.texto(q,200);if(!texto.isBlank()&&texto.length()<3)return List.of();par.addValue("q",texto);return jdbc.query("SELECT pe.id,pe.codigo,pe.nombre,c.nombre calendario FROM periodo_nomina pe JOIN calendario_nomina c ON c.id=pe.calendario_id WHERE pe.institucion_id=:institucion AND pe.estado='PROGRAMADO' AND c.activo AND strpos(lower(pe.codigo||' '||pe.nombre||' '||c.nombre),lower(:q))>0 ORDER BY pe.id LIMIT 11",par,(r,n)->new OpcionAutocompletado(r.getLong("id"),r.getString("codigo")+" · "+r.getString("nombre"),r.getString("calendario")));}
 // Clasificación antes de LIMIT/OFFSET: los filtros nunca se aplican sólo a una página en memoria.
 private static final String CANDIDATOS="""
 WITH datos AS (
 SELECT e.id,e.codigo,concat_ws(' ',e.nombres,e.primer_apellido,e.segundo_apellido) nombre,e.activo,
 l.situacion,l.fecha_ingreso,l.fecha_baja,sc.n sueldos,sc.sueldo,sc.base,sc.frecuencia,sc.moneda sueldo_moneda,sc.cubre sueldo_cubre,
 coalesce(ce.percepciones,0) percepciones,coalesce(ce.deducciones,0) deducciones,coalesce(ce.aportaciones,0) aportaciones,coalesce(ce.cubre,true) conceptos_cubren,
 EXISTS(SELECT 1 FROM nomina_borrador_empleado ne WHERE ne.empleado_id=e.id AND ne.activo AND ne.borrador_id<>:ignorar AND daterange(ne.fecha_inicio,ne.fecha_fin,'[]') && daterange(:inicio,:fin,'[]')) ocupado,
 jsonb_build_object('empleado',to_jsonb(e),'laboral',to_jsonb(l),'sueldos',coalesce(sc.fuentes,'[]'::jsonb),'conceptos',coalesce(ce.fuentes,'[]'::jsonb))::text fuentes
 FROM empleado e LEFT JOIN empleado_laboral l ON l.empleado_id=e.id
 LEFT JOIN LATERAL (SELECT count(*) n,min(s.importe_bruto) sueldo,min(s.base) base,min(s.frecuencia) frecuencia,min(s.moneda) moneda,
 bool_and(s.fecha_inicio<=:inicio AND (s.fecha_fin IS NULL OR s.fecha_fin>=:fin)) cubre,jsonb_agg(to_jsonb(s) ORDER BY s.id) fuentes
 FROM condicion_salarial s WHERE s.empleado_id=e.id AND s.institucion_id=:institucion AND s.estado='ACTIVA' AND s.fecha_inicio<=:fin AND (s.fecha_fin IS NULL OR s.fecha_fin>=:inicio)) sc ON true
 LEFT JOIN LATERAL (SELECT sum(a.importe) FILTER(WHERE a.naturaleza='PERCEPCION') percepciones,sum(a.importe) FILTER(WHERE a.naturaleza='DEDUCCION') deducciones,sum(a.importe) FILTER(WHERE a.naturaleza='APORTACION_PATRONAL') aportaciones,
 bool_and(a.fecha_inicio<=:inicio AND (a.fecha_fin IS NULL OR a.fecha_fin>=:fin) AND a.moneda=:moneda) cubre,jsonb_agg(to_jsonb(a) ORDER BY a.id) fuentes
 FROM concepto_empleado a WHERE a.empleado_id=e.id AND a.institucion_id=:institucion AND a.estado='ACTIVA' AND a.fecha_inicio<=:fin AND (a.fecha_fin IS NULL OR a.fecha_fin>=:inicio)) ce ON true
 WHERE e.institucion_id=:institucion AND (:empleado IS NULL OR e.id=:empleado) AND (:solo IS NULL OR e.id=:solo)
 AND strpos(lower(e.codigo||' '||concat_ws(' ',e.nombres,e.primer_apellido,e.segundo_apellido)),lower(:q))>0
 ), evaluados AS (
 SELECT *,CASE
 WHEN ocupado THEN 'NO_INCLUIDO|Ya incluido en un borrador vigente para fechas coincidentes.'
 WHEN NOT activo THEN 'NO_INCLUIDO|El expediente del empleado está inactivo.'
 WHEN fecha_ingreso>:fin THEN 'NO_INCLUIDO|El ingreso laboral es posterior al periodo.'
 WHEN fecha_baja<:inicio THEN 'NO_INCLUIDO|La baja laboral es anterior al periodo.'
 WHEN :frecuencia<>'MENSUAL' THEN 'NO_INCLUIDO|Frecuencia de calendario no mensual; requiere otra regla.'
 WHEN :parcial THEN 'REVISION|Periodo parcial; requiere revisión explícita, sin prorrateo.'
 WHEN situacion IS NULL OR situacion='POR_CONFIRMAR' OR fecha_ingreso IS NULL THEN 'REVISION|Faltan datos laborales confirmados para determinar elegibilidad.'
 WHEN fecha_ingreso>:inicio OR (fecha_baja IS NOT NULL AND fecha_baja<=:fin) THEN 'REVISION|Ingreso o baja dentro del periodo; requiere revisión explícita.'
 WHEN sueldos=0 THEN 'NO_INCLUIDO|Sin sueldo vigente que coincida con el periodo.'
 WHEN sueldos<>1 OR NOT sueldo_cubre THEN 'REVISION|El sueldo cambia o no cubre todo el periodo.'
 WHEN base<>'MENSUAL' OR frecuencia<>'MENSUAL' THEN 'NO_INCLUIDO|Sueldo de base o frecuencia distinta de mensual; no se convierte automáticamente.'
 WHEN sueldo_moneda<>:moneda THEN 'REVISION|La moneda salarial no coincide con la institucional.'
 WHEN NOT conceptos_cubren THEN 'REVISION|Un concepto empieza o termina dentro del periodo o usa otra moneda.'
 WHEN deducciones>sueldo+percepciones THEN 'REVISION|Las deducciones superan el sueldo y las percepciones; no se propone un importe negativo.'
 WHEN greatest(sueldo,percepciones,deducciones,aportaciones,sueldo+percepciones-deducciones)>99999999999999999.99 THEN 'REVISION|Los importes exceden la capacidad de este borrador.'
 ELSE 'LISTO|Configuración mensual compatible durante todo el periodo.' END evaluacion
 FROM datos), candidatos AS (SELECT *,split_part(evaluacion,'|',1) grupo,split_part(evaluacion,'|',2) motivo FROM evaluados)
 """;
 private MapSqlParameterSource candidatosParametros(Contexto c,FiltroNomina original,Long ignorar,Long solo){var f=original.normalizado();f.validar();if(f.filtroEmpleadoId()!=null)empleados.autorizar(f.filtroEmpleadoId(),true,false);return p(false).addValue("inicio",c.periodo().inicio()).addValue("fin",c.periodo().fin()).addValue("moneda",c.moneda()).addValue("frecuencia",c.periodo().frecuencia()).addValue("parcial",!c.advertencia().isEmpty()).addValue("ignorar",ignorar==null?0L:ignorar).addValue("solo",solo,java.sql.Types.BIGINT).addValue("empleado",f.filtroEmpleadoId(),java.sql.Types.BIGINT).addValue("q",f.q());}
 private RowMapper<Candidato> candidatoMap(Contexto c){return (r,n)->{boolean listo=r.getString("grupo").equals("LISTO");String fuentes=r.getString("fuentes");var sueldo=r.getBigDecimal("sueldo");var percepciones=r.getBigDecimal("percepciones");var deducciones=r.getBigDecimal("deducciones");return new Candidato(r.getLong("id"),r.getString("codigo"),r.getString("nombre"),r.getString("grupo"),r.getString("motivo"),listo?sueldo:null,listo?percepciones:null,listo?deducciones:null,listo?r.getBigDecimal("aportaciones"):null,listo?sueldo.add(percepciones).subtract(deducciones):null,c.moneda(),fuentes,sello(c.sello()+fuentes));};}
 public static String grupo(String g){return Set.of("LISTO","REVISION","NO_INCLUIDO").contains(Objects.toString(g,""))?g:"LISTO";}
 public Page<Candidato> candidatos(Long periodo,FiltroNomina original,String grupo){var c=contexto(periodo);var f=original.normalizado();var par=candidatosParametros(c,f,null,null).addValue("grupo",grupo(grupo));var pg=PageRequest.of(f.pagina(),f.tamanio());Long total=jdbc.queryForObject(CANDIDATOS+"SELECT count(*) FROM candidatos WHERE grupo=:grupo",par,Long.class);par.addValue("limite",pg.getPageSize()).addValue("offset",pg.getOffset());return new PageImpl<>(jdbc.query(CANDIDATOS+"SELECT * FROM candidatos WHERE grupo=:grupo ORDER BY id LIMIT :limite OFFSET :offset",par,candidatoMap(c)),pg,total==null?0:total);}
 public Map<String,Long> conteos(Long periodo,FiltroNomina filtro){var c=contexto(periodo);var par=candidatosParametros(c,filtro,null,null);var mapa=new LinkedHashMap<String,Long>();mapa.put("LISTO",0L);mapa.put("REVISION",0L);mapa.put("NO_INCLUIDO",0L);jdbc.query(CANDIDATOS+"SELECT grupo,count(*) n FROM candidatos GROUP BY grupo",par,r->{mapa.put(r.getString("grupo"),r.getLong("n"));});return mapa;}
 private FiltroNomina vacio(){return new FiltroNomina("","TODOS",null,null,null,null,null,null,null,null,0,25);}
 private Map<Long,String> tokens(List<String> tokens){if(tokens==null||tokens.isEmpty()||tokens.size()>100)throw regla("Selecciona entre 1 y 100 empleados listos de la página. Puedes crear otros borradores para los demás.");var ids=new TreeMap<Long,String>();for(String token:tokens){if(token==null||!token.matches("[0-9]+:[a-f0-9]{64}"))throw regla("La selección no es válida; vuelve a consultar los empleados.");try{var partes=token.split(":");Long id=Long.parseLong(partes[0]);if(id<=0||ids.put(id,partes[1])!=null)throw regla("No repitas empleados en la selección.");}catch(NumberFormatException e){throw regla("Empleado seleccionado no válido.");}}return ids;}
 private Previa evaluar(BorradorNominaForm form,Long ignorar,boolean bloquear){var ids=tokens(form.getSeleccion());var c=contexto(form.getPeriodoId());if(!Objects.equals(c.sello(),form.getSelloPeriodo()))throw regla("El periodo o calendario cambió. Consulta otra vez antes de revisar y guardar.");if(form.getNombre()==null||form.getNombre().isBlank()||form.getNombre().length()>150)throw regla("Captura un nombre de máximo 150 caracteres.");motivo(form.getMotivo());
  if(bloquear){var par=p(true).addValue("ids",ids.keySet());var encontrados=jdbc.queryForList("SELECT id FROM empleado WHERE institucion_id=:institucion AND id IN (:ids) ORDER BY id FOR UPDATE",par,Long.class);if(encontrados.size()!=ids.size())throw new AccessDeniedException("Selección de empleados no autorizada");jdbc.queryForList("SELECT empleado_id FROM empleado_laboral WHERE empleado_id IN (:ids) ORDER BY empleado_id FOR UPDATE",par,Long.class);}
  var filas=new ArrayList<Candidato>();for(var entrada:ids.entrySet()){var par=candidatosParametros(c,vacio(),ignorar,entrada.getKey());var candidato=jdbc.query(CANDIDATOS+"SELECT * FROM candidatos",par,candidatoMap(c)).stream().findFirst().orElseThrow(()->new AccessDeniedException("Empleado no autorizado"));if(!candidato.grupo().equals("LISTO"))throw regla(candidato.nombre()+": "+candidato.motivo());if(!candidato.sello().equals(entrada.getValue()))throw regla("La configuración de "+candidato.nombre()+" cambió desde la selección. Consulta otra vez; no se guardó el borrador.");filas.add(candidato);}
  return new Previa(c,List.copyOf(filas),totales(filas));
 }
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Previa previsualizar(BorradorNominaForm f){return evaluar(f,null,false);}
 public static Totales totales(List<Candidato> filas){return new Totales(filas.size(),filas.stream().map(Candidato::sueldo).reduce(BigDecimal.ZERO,BigDecimal::add),filas.stream().map(Candidato::percepciones).reduce(BigDecimal.ZERO,BigDecimal::add),filas.stream().map(Candidato::deducciones).reduce(BigDecimal.ZERO,BigDecimal::add),filas.stream().map(Candidato::aportaciones).reduce(BigDecimal.ZERO,BigDecimal::add),filas.stream().map(Candidato::propuesto).reduce(BigDecimal.ZERO,BigDecimal::add));}
 @Transactional public Long guardar(BorradorNominaForm f){var par=p(true);activa(par);bloquearPeriodo(f.getPeriodoId());var previa=evaluar(f,null,true);Long id=jdbc.queryForObject("INSERT INTO nomina_borrador(institucion_id,periodo_id,nombre,motivo_operacion,creado_por_id,actualizado_por_id) VALUES(:institucion,:periodo,:nombre,:motivo,:actor,:actor) RETURNING id",par.addValue("periodo",f.getPeriodoId()).addValue("nombre",f.getNombre().strip()).addValue("motivo",f.getMotivo().strip()),Long.class);registrarRevision(id,1,previa,f.getMotivo());return id;}
 private void registrarRevision(Long id,int numero,Previa previa,String motivo){var c=previa.contexto();var per=c.periodo();var par=p(true).addValue("id",id).addValue("numero",numero).addValue("periodo",per.id()).addValue("codigo",per.codigo()).addValue("nombre",per.nombre()).addValue("cal",per.calendarioId()).addValue("calTexto",c.calendario()).addValue("inicio",per.inicio()).addValue("fin",per.fin()).addValue("pago",per.pago()).addValue("moneda",c.moneda()).addValue("datos",c.fuentes()).addValue("sello",c.sello()).addValue("motivo",motivo.strip());jdbc.update("INSERT INTO nomina_borrador_revision(borrador_id,numero,institucion_id,periodo_id,periodo_codigo,periodo_nombre,calendario_id,calendario_texto,fecha_inicio,fecha_fin,fecha_pago,moneda,datos_periodo,sello_periodo,motivo,creado_por_id) VALUES(:id,:numero,:institucion,:periodo,:codigo,:nombre,:cal,:calTexto,:inicio,:fin,:pago,:moneda,cast(:datos as jsonb),:sello,:motivo,:actor)",par);
  for(var e:previa.candidatos())jdbc.update("INSERT INTO nomina_borrador_empleado(borrador_id,revision,institucion_id,periodo_id,empleado_id,empleado_codigo,empleado_nombre,fecha_inicio,fecha_fin,sueldo,percepciones,deducciones,aportaciones,propuesto,moneda,fuentes,sello) VALUES(:id,:numero,:institucion,:periodo,:empleado,:empCodigo,:empNombre,:inicio,:fin,:sueldo,:percepciones,:deducciones,:aportaciones,:propuesto,:moneda,cast(:fuentes as jsonb),:empSello)",par.addValue("empleado",e.id()).addValue("empCodigo",e.codigo()).addValue("empNombre",e.nombre()).addValue("sueldo",e.sueldo()).addValue("percepciones",e.percepciones()).addValue("deducciones",e.deducciones()).addValue("aportaciones",e.aportaciones()).addValue("propuesto",e.propuesto()).addValue("fuentes",e.fuentes()).addValue("empSello",e.sello()));
 }
 private static final String SELECT="SELECT b.*,r.periodo_codigo,r.periodo_nombre,r.calendario_texto,r.fecha_inicio,r.fecha_fin,r.fecha_pago,r.moneda,r.sello_periodo,(SELECT count(*) FROM nomina_borrador_empleado ne WHERE ne.borrador_id=b.id AND ne.revision=b.revision_actual) cantidad,(SELECT coalesce(sum(ne.propuesto),0) FROM nomina_borrador_empleado ne WHERE ne.borrador_id=b.id AND ne.revision=b.revision_actual) propuesto ";
 private static final String FROM=" FROM nomina_borrador b JOIN nomina_borrador_revision r ON r.borrador_id=b.id AND r.numero=b.revision_actual ";
 private static final RowMapper<Borrador> BORRADOR=(r,n)->new Borrador(r.getLong("id"),r.getLong("periodo_id"),r.getString("nombre"),r.getString("estado"),r.getInt("revision_actual"),r.getLong("version"),r.getString("motivo_operacion"),r.getString("periodo_codigo"),r.getString("periodo_nombre"),r.getString("calendario_texto"),r.getObject("fecha_inicio",LocalDate.class),r.getObject("fecha_fin",LocalDate.class),r.getObject("fecha_pago",LocalDate.class),r.getString("moneda"),r.getString("sello_periodo"),r.getInt("cantidad"),r.getBigDecimal("propuesto"));
 public Borrador obtener(Long id){return obtener(id,false);}
 private Borrador obtener(Long id,boolean bloquear){return jdbc.query(SELECT+FROM+" WHERE b.institucion_id=:institucion AND b.id=:id"+(bloquear?" FOR UPDATE OF b":""),p(bloquear).addValue("id",id),BORRADOR).stream().findFirst().orElseThrow(()->new AccessDeniedException("Borrador no autorizado"));}
 private MapSqlParameterSource filtros(FiltroNomina f){f.validar();if(f.filtroCalendarioId()!=null)programacion.calendario(f.filtroCalendarioId());if(f.filtroPeriodoId()!=null)programacion.periodo(f.filtroPeriodoId());if(f.filtroEmpleadoId()!=null)empleados.autorizar(f.filtroEmpleadoId(),true,false);return p(false).addValue("q",f.q()).addValue("estado",f.estado()).addValue("cal",f.filtroCalendarioId(),java.sql.Types.BIGINT).addValue("periodo",f.filtroPeriodoId(),java.sql.Types.BIGINT).addValue("empleado",f.filtroEmpleadoId(),java.sql.Types.BIGINT).addValue("desde",f.desde(),java.sql.Types.DATE).addValue("hasta",f.hasta(),java.sql.Types.DATE);}
 private static final String WHERE=" WHERE b.institucion_id=:institucion AND (:estado='TODOS' OR b.estado=:estado) AND (:cal IS NULL OR r.calendario_id=:cal) AND (:periodo IS NULL OR b.periodo_id=:periodo) AND (:desde IS NULL OR r.fecha_fin>=:desde) AND (:hasta IS NULL OR r.fecha_inicio<=:hasta) AND (:empleado IS NULL OR EXISTS(SELECT 1 FROM nomina_borrador_empleado ne WHERE ne.borrador_id=b.id AND ne.revision=b.revision_actual AND ne.empleado_id=:empleado)) AND strpos(lower(b.nombre||' '||r.periodo_codigo||' '||r.periodo_nombre||' '||r.calendario_texto),lower(:q))>0 ";
 public Page<Borrador> listar(FiltroNomina original){var f=original.normalizado();var par=filtros(f);var pg=PageRequest.of(f.pagina(),f.tamanio());Long total=jdbc.queryForObject("SELECT count(*)"+FROM+WHERE,par,Long.class);par.addValue("limite",pg.getPageSize()).addValue("offset",pg.getOffset());return new PageImpl<>(jdbc.query(SELECT+FROM+WHERE+" ORDER BY b.id LIMIT :limite OFFSET :offset",par,BORRADOR),pg,total==null?0:total);}
 private static final RowMapper<Guardado> GUARDADO=(r,n)->new Guardado(r.getLong("id"),r.getLong("empleado_id"),r.getString("empleado_codigo"),r.getString("empleado_nombre"),r.getBigDecimal("sueldo"),r.getBigDecimal("percepciones"),r.getBigDecimal("deducciones"),r.getBigDecimal("aportaciones"),r.getBigDecimal("propuesto"),r.getString("moneda"),r.getString("sello"),r.getInt("revision"));
 public Cobertura cobertura(Long id,int revision){obtener(id);return jdbc.query("SELECT * FROM nomina_borrador_revision WHERE borrador_id=:id AND institucion_id=:institucion AND numero=:revision",p(false).addValue("id",id).addValue("revision",revision),(r,n)->new Cobertura(r.getString("calendario_texto"),r.getString("periodo_codigo"),r.getString("periodo_nombre"),r.getObject("fecha_inicio",LocalDate.class),r.getObject("fecha_fin",LocalDate.class),r.getObject("fecha_pago",LocalDate.class),r.getString("moneda"))).stream().findFirst().orElseThrow(()->regla("Revisión no disponible."));}
 public Page<Guardado> guardados(Long id,int revision,int pagina){var b=obtener(id);if(revision<1||revision>b.revision())throw regla("Revisión no disponible.");var par=p(false).addValue("id",id).addValue("revision",revision);Long total=jdbc.queryForObject("SELECT count(*) FROM nomina_borrador_empleado WHERE borrador_id=:id AND institucion_id=:institucion AND revision=:revision",par,Long.class);var pg=PageRequest.of(Math.max(0,pagina),25);par.addValue("offset",pg.getOffset());return new PageImpl<>(jdbc.query("SELECT * FROM nomina_borrador_empleado WHERE borrador_id=:id AND institucion_id=:institucion AND revision=:revision ORDER BY id LIMIT 25 OFFSET :offset",par,GUARDADO),pg,total==null?0:total);}
 private List<Guardado> todos(Borrador b){return jdbc.query("SELECT * FROM nomina_borrador_empleado WHERE borrador_id=:id AND institucion_id=:institucion AND revision=:revision ORDER BY empleado_id LIMIT 101",p(false).addValue("id",b.id()).addValue("revision",b.revision()),GUARDADO);}
 public Guardado empleadoGuardado(Long id,Long fila){obtener(id);return jdbc.query("SELECT * FROM nomina_borrador_empleado WHERE borrador_id=:id AND institucion_id=:institucion AND id=:fila",p(false).addValue("id",id).addValue("fila",fila),GUARDADO).stream().findFirst().orElseThrow(()->new AccessDeniedException("Empleado histórico no autorizado"));}
 public Totales totalesGuardados(Long id,int revision){obtener(id);return jdbc.queryForObject("SELECT count(*) n,coalesce(sum(sueldo),0) sueldo,coalesce(sum(percepciones),0) percepciones,coalesce(sum(deducciones),0) deducciones,coalesce(sum(aportaciones),0) aportaciones,coalesce(sum(propuesto),0) propuesto FROM nomina_borrador_empleado WHERE borrador_id=:id AND institucion_id=:institucion AND revision=:revision",p(false).addValue("id",id).addValue("revision",revision),(r,n)->new Totales(r.getInt("n"),r.getBigDecimal("sueldo"),r.getBigDecimal("percepciones"),r.getBigDecimal("deducciones"),r.getBigDecimal("aportaciones"),r.getBigDecimal("propuesto")));}
 public List<Linea> lineas(Long id,Long fila){empleadoGuardado(id,fila);var par=p(false).addValue("id",id).addValue("fila",fila);return jdbc.query("SELECT x->>'puesto_codigo' codigo,x->>'puesto_nombre' nombre,'SUELDO' naturaleza,(x->>'importe_bruto')::numeric importe,x->>'fecha_inicio' inicio,x->>'fecha_fin' fin FROM nomina_borrador_empleado ne CROSS JOIN LATERAL jsonb_array_elements(ne.fuentes->'sueldos') x WHERE ne.id=:fila AND ne.borrador_id=:id AND ne.institucion_id=:institucion UNION ALL SELECT x->>'concepto_codigo',x->>'concepto_nombre',x->>'naturaleza',(x->>'importe')::numeric,x->>'fecha_inicio',x->>'fecha_fin' FROM nomina_borrador_empleado ne CROSS JOIN LATERAL jsonb_array_elements(ne.fuentes->'conceptos') x WHERE ne.id=:fila AND ne.borrador_id=:id AND ne.institucion_id=:institucion",par,(r,n)->new Linea(r.getString("codigo"),r.getString("nombre"),r.getString("naturaleza"),r.getBigDecimal("importe"),r.getString("inicio"),r.getString("fin")));}
 public Page<Revision> revisiones(Long id,int pagina){obtener(id);var pg=PageRequest.of(Math.max(0,pagina),20);var par=p(false).addValue("id",id).addValue("offset",pg.getOffset());Long total=jdbc.queryForObject("SELECT count(*) FROM nomina_borrador_revision WHERE borrador_id=:id AND institucion_id=:institucion",par,Long.class);return new PageImpl<>(jdbc.query("SELECT r.numero,to_char(r.creado_en AT TIME ZONE i.zona_horaria,'DD/MM/YYYY HH24:MI') fecha,u.username,r.motivo FROM nomina_borrador_revision r JOIN institucion i ON i.id=r.institucion_id JOIN usuario u ON u.id=r.creado_por_id WHERE r.borrador_id=:id AND r.institucion_id=:institucion ORDER BY r.numero DESC LIMIT 20 OFFSET :offset",par,(r,n)->new Revision(r.getInt("numero"),r.getString("fecha"),r.getString("username"),r.getString("motivo"))),pg,total==null?0:total);}
 public Page<Historia> historial(Long id,int pagina){obtener(id);var par=p(false).addValue("id",id).addValue("offset",Math.max(0,pagina)*20L);Long total=jdbc.queryForObject("SELECT count(*) FROM nomina_borrador_historial WHERE borrador_id=:id AND institucion_id=:institucion",par,Long.class);return new PageImpl<>(jdbc.query("SELECT to_char(h.ocurrido_en AT TIME ZONE i.zona_horaria,'DD/MM/YYYY HH24:MI') fecha,u.username,h.operacion,h.datos->'despues'->>'motivo_operacion' motivo,(h.datos->'despues'->>'revision_actual')::integer revision FROM nomina_borrador_historial h JOIN usuario u ON u.id=h.usuario_id JOIN institucion i ON i.id=h.institucion_id WHERE h.borrador_id=:id AND h.institucion_id=:institucion ORDER BY h.id DESC LIMIT 20 OFFSET :offset",par,(r,n)->new Historia(r.getString("fecha"),r.getString("username"),r.getString("operacion"),r.getString("motivo"),r.getInt("revision"))),PageRequest.of(Math.max(0,pagina),20),total==null?0:total);}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Previa actualizacion(Long id){var b=obtener(id);if(!b.estado().equals("BORRADOR"))throw regla("El borrador cancelado es sólo consulta.");var c=contexto(b.periodoId());var filas=new ArrayList<Candidato>();for(var e:todos(b))filas.add(jdbc.query(CANDIDATOS+"SELECT * FROM candidatos",candidatosParametros(c,vacio(),id,e.empleadoId()),candidatoMap(c)).stream().findFirst().orElseThrow(()->regla("Empleado original no disponible; conserva el historial y revisa el caso.")));return new Previa(c,List.copyOf(filas),filas.stream().allMatch(e->e.grupo().equals("LISTO"))?totales(filas):null);}
 @Transactional public void actualizar(Long id,Long enviada,BorradorNominaForm form){var par=p(true);activa(par);var inicial=obtener(id);if(!Objects.equals(inicial.periodoId(),form.getPeriodoId()))throw regla("El periodo del borrador no se puede cambiar.");bloquearPeriodo(inicial.periodoId());var b=obtener(id,true);version(b.version(),enviada);if(!b.estado().equals("BORRADOR"))throw regla("El borrador cancelado es sólo consulta.");var seleccion=tokens(form.getSeleccion());if(!new TreeSet<>(todos(b).stream().map(Guardado::empleadoId).toList()).equals(seleccion.keySet()))throw regla("Actualizar conserva los empleados originales. Para otra selección cancela este borrador y prepara uno nuevo.");var previa=evaluar(form,id,true);jdbc.update("UPDATE nomina_borrador_empleado SET activo=false WHERE borrador_id=:id AND institucion_id=:institucion AND activo",par.addValue("id",id));registrarRevision(id,b.revision()+1,previa,form.getMotivo());jdbc.update("UPDATE nomina_borrador SET nombre=:nombre,revision_actual=revision_actual+1,motivo_operacion=:motivo,actualizado_por_id=:actor,actualizado_en=CURRENT_TIMESTAMP,version=version+1 WHERE id=:id AND institucion_id=:institucion",par.addValue("nombre",form.getNombre().strip()).addValue("motivo",form.getMotivo().strip()));}
 @Transactional public void cancelar(Long id,Long enviada,String motivo){var par=p(true);activa(par);motivo(motivo);var inicial=obtener(id);bloquearPeriodo(inicial.periodoId());var b=obtener(id,true);version(b.version(),enviada);if(!b.estado().equals("BORRADOR"))throw regla("El borrador ya está cancelado; no se realizó otra operación.");jdbc.update("UPDATE nomina_borrador_empleado SET activo=false WHERE borrador_id=:id AND institucion_id=:institucion AND activo",par.addValue("id",id));jdbc.update("UPDATE nomina_borrador SET estado='CANCELADO',motivo_operacion=:motivo,actualizado_por_id=:actor,actualizado_en=CURRENT_TIMESTAMP,version=version+1 WHERE id=:id AND institucion_id=:institucion",par.addValue("motivo",motivo.strip()));}
 public String advertencia(Borrador b){try{var c=contexto(b.periodoId());return c.sello().equals(b.selloPeriodo())?"":"El periodo o calendario cambió. Esta vista conserva la revisión guardada; revisa Actualizar desde configuración antes de continuar.";}catch(ReglaNegocioException e){return e.getMessage()+" La copia guardada permanece para consulta; no es una nómina autorizada.";}}
 private static ReglaNegocioException regla(String m){return new ReglaNegocioException(m);}
}
